def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            perimeter = {(y, x) for y in range(r0, r1+1) for x in range(c0, c1+1)
                         if y in (r0, r1) or x in (c0, c1)}
            if set(cells) != perimeter or (r1-r0) != (c1-c0):
                continue
            fill = 7 if (r1-r0+1) % 2 == 1 else 2
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    if out[y][x] == background:
                        out[y][x] = fill
    return out
